head.script:
scwin.screenId = "jldbnf30000";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = function () {
    /* sdd-asis-lifecycle:begin initPageIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_searchStripBndListReq').set('pageIndex', "1");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $('#paging7 table:first-child').attr('align', 'center');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 3개다(strip#searchstripbndlist vs strip#searchbndspecbynew vs strip#searchbndspecbyaddmerge) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.header_cd = undefined; try { scwin.header_cd = /* sdd-asis-lifecycle:begin header_cd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.util.getComponent('ipt_bndMktactTpCd').getValue()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf30000' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf30000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_searchStripBndList_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_searchStripBndList_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_searchStripBndList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.searchStripBndList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30000.btn_searchStripBndList_onclick' }); }
};

/**
 * @event
 * @name scwin.ipt_isuNm_onkeydown
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_isuNm_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_isuNm_onkeydown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(event.keyCode==13){replacePercent(selfVar);await scwin.searchStripBndList();}
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30000.ipt_isuNm_onkeydown' }); }
};

/**
 * @event
 * @name scwin.ipt_isuNm_onblur
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_isuNm_onblur = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_isuNm_onblur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        replacePercent(selfVar);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30000.ipt_isuNm_onblur' }); }
};

/**
 * @event
 * @name scwin.grd_result_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_result'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.searchBndSpec === 'function') { await scwin.searchBndSpec(r["stdCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.searchBndSpec (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchBndSpec'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_searchStripBndList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchStripBndList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchStripBndList",
        method: "post",
        action: "/strip/strip.do?method=searchStripBndList",
        ref: "dma_searchStripBndListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf30000.tx_fn_searchStripBndList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_searchBndSpec
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchBndSpec = async function () {
    const sbmOptions = {
        id: "tx_fn_searchBndSpec",
        method: "post",
        action: "/strip/strip.do?method=searchBndSpecByNew",
        ref: "dma_searchBndSpecReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf30000.tx_fn_searchBndSpec" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchStripBndList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchStripBndList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchStripBndList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.searchForm || { elements: [] });
    fm.action = '/strip/strip.do?method=searchStripBndList';
    await scwin.tx_fn_searchStripBndList();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchBndSpec
 * @author Inswave
 * @date 2026. 09. 29
 * @param stdCd
 * @returns
 * @hidden N
*/
scwin.searchBndSpec = async function (stdCd) {
    /* sdd-asis-lifecycle:begin fn_searchBndSpec — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent("dma_searchStripBndListReq").set("stdCd", stdCd);
    const bndMktactTpCd = $c.util.getComponent("dma_searchStripBndListReq").get("bndMktactTpCd");
    if (bndMktactTpCd === "401") {
        fm.action = '/strip/strip.do?method=searchBndSpecByNew';
    } else {
        fm.action = '/strip/strip.do?method=searchBndSpecByAddMerge';
    }
    await scwin.tx_fn_searchBndSpec();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_79_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_79_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchStripBndListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_79.page' }); } scwin.searchStripBndList(); };
